import NavMenu from "./NavMenu";

export function Details(){
    return(
        <div>
            <NavMenu></NavMenu>
            <div class="container">
                <br></br>
                <h1>
                    Jelenlegi projektem részletei
                </h1>
                <br></br>
                <p>
                    Mindig is úgy gondoltam, hogy matematikát szemléltetni egyszerübb ábrákkal és rajzokkal. Ha csak szöveget írnánk végig, akkor hamar unalmas lenne a diákoknak, persze egy minimális szöveg szükséges, ahhoz hogy a gondolatmenetet és a koncepciót felvezessük. Ezért gondoltam, hogy inkább egy olyan megközelítést használok ami több képen és rajzon keresztül próbál ösztönzőbb lenni a matematika tanuláshoz.
                </p>
            </div>
        </div>
    )
}

export default Details;
